  `PATH_IMG_MEDIUM_PROFILE` varchar(250) DEFAULT NULL,
  `IS_SPOT_OWNER` tinyint(1) DEFAULT '0',
  `FACEBOOKID` varchar(250) DEFAULT NULL,
  `HOTMAILID` varchar(250) DEFAULT NULL,
  `GOOGLEID` varchar(250) DEFAULT NULL,
  `YAHOOKID` varchar(250) DEFAULT NULL,
  `ROLE` tinyint(1) NOT NULL DEFAULT '1',
