  `PATH_IMG_PROFILE3` varchar(250) DEFAULT NULL,
  `PATH_IMG_PROFILE4` varchar(250) DEFAULT NULL,
  `MAXDISTANCEEVENT` smallint(5) DEFAULT '200',
  `MAXDISTANCESPOT` smallint(5) DEFAULT '200',
  `MAXDISTANCERIDER` smallint(5) DEFAULT '200',
  `LANG` varchar(10) DEFAULT 'EN',
